<?php
/** Owner-scoped, opt-in marketing over the customer's own official Cloud API connection. */
class WhatsAppMarketingService
{
    protected PDO $pdo; private $factory;
    public function __construct(?PDO $pdo=null,?callable $factory=null){$this->pdo=$pdo??Database::getInstance()->getConnection();$this->factory=$factory;}
    protected function q(string $sql,array $args=[]): PDOStatement{$s=$this->pdo->prepare($sql);$s->execute($args);return $s;}
    public function owned(int $uid,int $wid): array{$w=$this->q('SELECT id,company_name FROM websites WHERE id=? AND user_id=?',[$wid,$uid])->fetch(PDO::FETCH_ASSOC);if(!$w)throw new InvalidArgumentException('Website not found');return $w;}
    private function conn(int $uid,int $wid): array{$this->owned($uid,$wid);$r=WhatsAppCloudAPI::connectionRow($wid);if(!$r||(int)$r['user_id']!==$uid||!preg_match('/^[0-9]{1,32}$/D',(string)$r['external_account_id'])||!preg_match('/^[0-9]{1,32}$/D',(string)$r['external_location_id']))throw new InvalidArgumentException('Connect your website to the official WhatsApp Cloud API first');return $r;}
    private static function connectionHash(array $r): string{return hash('sha256',$r['id'].'|'.$r['external_account_id'].'|'.$r['external_location_id'].'|'.$r['access_token']);}
    private function api(int $uid,int $wid): object{$r=$this->conn($uid,$wid);$api=$this->factory?($this->factory)($r):WhatsAppCloudAPI::forWebsite($wid);if(!$api)throw new InvalidArgumentException('WhatsApp credentials cannot be read. Reconnect the account.');return $api;}
    private function lock(string $key,callable $fn){if(!ExternalExecution::lock($key))throw new RuntimeException('Another WhatsApp operation is in progress. Try again.');try{return $fn();}finally{ExternalExecution::unlock($key);}}
    public static function phone(string $input): string{$s=trim($input);if(!preg_match('/^[+0-9 ()-]+$/D',$s))throw new InvalidArgumentException('Use an international phone number including its country code');$p=preg_replace('/[^0-9]/','',$s);if(str_starts_with($p,'00'))$p=substr($p,2);if(!preg_match('/^[1-9][0-9]{7,14}$/D',$p))throw new InvalidArgumentException('Use an international phone number including its country code; local numbers are not guessed');return $p;}
    private static function text($v,string $name,int $max): string{if(!is_scalar($v))throw new InvalidArgumentException('Invalid '.$name);$s=trim((string)$v);if($s===''||mb_strlen($s)>$max)throw new InvalidArgumentException('Invalid '.$name);return $s;}
    public static function compatible(string $contact,string $template): bool{return str_contains($contact,'_')?$contact===$template:explode('_',$template)[0]===$contact;}
    public function contact(int $uid,int $wid,array $input): array
    {
