        if(!preg_match('/^[a-z]{2,3}(?:_[A-Z]{2})?$/D',$language))throw new InvalidArgumentException('Use a language code such as en, fr, ar or en_US');
        $state=(string)($input['consent_state']??'pending');if(!in_array($state,['pending','opted_in','opted_out'],true))throw new InvalidArgumentException('Invalid consent state');$rawNote=$input['consent_note']??'';if(!is_scalar($rawNote))throw new InvalidArgumentException('Invalid consent evidence');$note=trim((string)$rawNote);if(mb_strlen($note)>500)throw new InvalidArgumentException('Consent note is too long');if($state==='opted_in'&&mb_strlen($note)<5)throw new InvalidArgumentException('Record the source of the customer’s explicit WhatsApp marketing permission');
