            // Imports and ordinary edits cannot restore an opted-out contact.
            if($existing&&$existing['consent_state']==='opted_out'&&$state==='pending')$state='opted_out';
            if($existing&&$existing['consent_state']==='opted_out'&&$state==='opted_in'&&$note===$existing['consent_note'])throw new InvalidArgumentException('A new explicit opt-in needs new consent evidence');
            $this->q('INSERT INTO wa_marketing_contacts(user_id,website_id,phone,name,language,consent_state,consent_note,consented_at,opted_out_at) VALUES(?,?,?,?,?,?,?, ?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),language=VALUES(language),consent_state=VALUES(consent_state),consent_note=VALUES(consent_note),consented_at=VALUES(consented_at),opted_out_at=VALUES(opted_out_at)',[$uid,$wid,$phone,$name,$language,$state,$note,$state==='opted_in'?gmdate('Y-m-d H:i:s'):null,$state==='opted_out'?gmdate('Y-m-d H:i:s'):null]);
            $row=$this->q('SELECT * FROM wa_marketing_contacts WHERE user_id=? AND website_id=? AND phone=?',[$uid,$wid,$phone])->fetch(PDO::FETCH_ASSOC);
            $this->q('INSERT INTO wa_marketing_consent_events(contact_id,user_id,website_id,state,evidence) VALUES(?,?,?,?,?)',[$row['id'],$uid,$wid,$state,$note]);$this->pdo->commit();return $row;
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function importCrm(int $uid,int $wid,array $ids): array
    {
        $this->owned($uid,$wid);if(!$ids||count($ids)>200)throw new InvalidArgumentException('Choose 1–200 CRM contacts');$rows=[];
        foreach(array_unique($ids) as $id){$row=$this->q("SELECT name,phone,language FROM crm_contacts WHERE id=? AND user_id=? AND status='active'",[(int)$id,$uid])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new InvalidArgumentException('Owned CRM contact not found; nothing was imported');$rows[]=$row;}
        $result=['imported'=>0,'invalid'=>0];foreach($rows as $c){try{$p=self::phone((string)$c['phone']);if($this->q('SELECT id FROM wa_marketing_contacts WHERE user_id=? AND website_id=? AND phone=?',[$uid,$wid,$p])->fetchColumn())continue;$this->contact($uid,$wid,['name'=>$c['name'],'phone'=>$p,'language'=>$c['language']?:ContentLanguageService::forWebsite($wid,$uid),'consent_state'=>'pending','consent_note'=>'Imported from CRM; marketing consent not inferred']);$result['imported']++;}catch(InvalidArgumentException $e){$result['invalid']++;}}return $result;
    }
    public function contacts(int $uid,int $wid,int $page=1): array{$this->owned($uid,$wid);if($page<1||$page>10000)throw new InvalidArgumentException('Invalid page');return $this->q('SELECT id,phone,name,language,consent_state,consent_note,consented_at,opted_out_at,last_accepted_at FROM wa_marketing_contacts WHERE user_id=? AND website_id=? ORDER BY id DESC LIMIT 100 OFFSET '.(($page-1)*100),[$uid,$wid])->fetchAll(PDO::FETCH_ASSOC);}
    public static function inspectTemplate(array $t): array
    {
        $body='';$supported=true;$reason=null;foreach(($t['components']??[]) as $component)if(strtoupper((string)($component['type']??''))==='BODY')$body=(string)($component['text']??'');
        try{WhatsAppTemplateComponents::requirements($t['components']??[]);}catch(InvalidArgumentException $e){$supported=false;$reason=$e->getMessage();}
        $count=0;
        try{$vars=WhatsAppTemplateComponents::variables($body);$count=count($vars);$named=$vars&&!ctype_digit($vars[0]);if($body===''||($named&&strtoupper($t['parameter_format']??'POSITIONAL')!=='NAMED')||(!$named&&$vars&&strtoupper($t['parameter_format']??'POSITIONAL')==='NAMED'))throw new InvalidArgumentException('Template variable format does not match its definition');}catch(InvalidArgumentException $e){$supported=false;$reason=$e->getMessage();}
        if(($t['category']??'')!=='MARKETING'){$supported=false;$reason='Select a MARKETING category template';}
