    }
    public function syncTemplates(int $uid,int $wid): array
    {
        return $this->lock('wa_templates:'.$uid.':'.$wid,function()use($uid,$wid){$connection=$this->conn($uid,$wid);$api=$this->api($uid,$wid);$items=[];$after=null;$seen=[];
            for($page=0;$page<10;$page++){$r=$api->marketingTemplates($after);if(empty($r['ok']))throw new RuntimeException('Unable to read templates from Meta. Check permissions and reconnect if needed.');if(!is_array($r['items']??null))throw new RuntimeException('Invalid Meta template response');array_push($items,...$r['items']);$after=$r['after']??null;if(!$after)break;if(isset($seen[$after])||$page===9)throw new RuntimeException('Template list is incomplete. Narrow the account or request a larger template import.');$seen[$after]=true;}
            if(self::connectionHash($this->conn($uid,$wid))!==self::connectionHash($connection))throw new RuntimeException('Connection changed during template refresh');
            $this->pdo->beginTransaction();try{$this->q("UPDATE wa_marketing_templates SET status='MISSING',supported=0 WHERE user_id=? AND website_id=?",[$uid,$wid]);foreach($items as $t){$v=self::inspectTemplate($t);$name=self::text($t['name']??'','template name',128);$lang=self::text($t['language']??'','template language',12);$this->q('INSERT INTO wa_marketing_templates(user_id,website_id,name,language,status,supported,body,parameter_count,reason,content_hash,connection_hash,components_json,checked_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE status=VALUES(status),supported=VALUES(supported),body=VALUES(body),parameter_count=VALUES(parameter_count),reason=VALUES(reason),content_hash=VALUES(content_hash),connection_hash=VALUES(connection_hash),components_json=VALUES(components_json),checked_at=VALUES(checked_at)',[$uid,$wid,$name,$lang,(string)($t['status']??'UNKNOWN'),$v['supported']?1:0,$v['body'],$v['parameter_count'],$v['reason'],$v['content_hash'],self::connectionHash($connection),json_encode($t['components']??[],JSON_THROW_ON_ERROR)]);}$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}return $this->templates($uid,$wid);
        });
    }
    public function templates(int $uid,int $wid): array{$this->owned($uid,$wid);return $this->q('SELECT id,name,language,status,supported,body,parameter_count,reason,checked_at,components_json FROM wa_marketing_templates WHERE user_id=? AND website_id=? ORDER BY name,language',[$uid,$wid])->fetchAll(PDO::FETCH_ASSOC);}
    public function createTemplate(int $uid,int $wid,array $input): array
    {$name=self::text($input['name']??'','template name',128);$lang=self::text($input['language']??'en','language',12);$body=self::text($input['body']??'','template body',1024);if(!preg_match('/^[a-z0-9_]+$/D',$name)||!preg_match('/^[a-z]{2,3}(?:_[A-Z]{2})?$/D',$lang))throw new InvalidArgumentException('Use a lowercase template name and a valid language code');if(!preg_match('/\bSTOP\b/i',$body))throw new InvalidArgumentException('Include a Reply STOP opt-out instruction in the template');if(preg_match('/^\{\{|\}\}$/',$body))throw new InvalidArgumentException('Variables cannot be first or last in a template');$t=['name'=>$name,'language'=>$lang,'category'=>'MARKETING','components'=>[['type'=>'BODY','text'=>$body]]];$v=self::inspectTemplate($t);if(!$v['supported'])throw new InvalidArgumentException($v['reason']);$examples=$input['examples']??[];if(!is_array($examples)||count($examples)!==$v['parameter_count'])throw new InvalidArgumentException('Provide one sample for each template variable');foreach($examples as &$sample)$sample=self::text($sample,'sample',500);unset($sample);if($examples)$t['components'][0]['example']=['body_text'=>[array_values($examples)]];
        $api=$this->api($uid,$wid);$key='wa_template_create:'.$uid.':'.$wid.':'.$name.':'.$lang.':'.hash('sha256',json_encode($t));$r=ExternalExecution::run($key,$uid,function()use($api,$t){$r=$api->createTemplate($t);return ['success'=>!empty($r['ok']),'status'=>$r['status']??null,'http_code'=>$r['http_code']??0,'error'=>empty($r['ok'])?'Meta did not confirm template creation. Check WhatsApp Manager before retrying.':null];});if(empty($r['success']))throw new RuntimeException($r['error']);return ['status'=>$r['status']??'PENDING','message'=>'Submitted to Meta. Approval is required before this template can be sent.'];
    }
    private function template(int $uid,int $wid,int $id): array{$t=$this->q('SELECT * FROM wa_marketing_templates WHERE id=? AND user_id=? AND website_id=?',[$id,$uid,$wid])->fetch(PDO::FETCH_ASSOC);if(!$t||$t['status']!=='APPROVED'||!$t['supported'])throw new InvalidArgumentException('Choose an approved, supported marketing template');if($t['connection_hash']!==self::connectionHash($this->conn($uid,$wid)))throw new InvalidArgumentException('Refresh templates for the current connection');return $t;}
    public function create(int $uid,int $wid,array $input): array
    {
        $this->owned($uid,$wid);$t=$this->template($uid,$wid,(int)($input['template_id']??0));$name=self::text($input['name']??'','campaign name',190);$parameters=$input['parameters']??[];if(!is_array($parameters)||!array_is_list($parameters)||count($parameters)!==(int)$t['parameter_count'])throw new InvalidArgumentException('Fill every template variable');foreach($parameters as &$p)$p=self::text($p,'parameter',1000);unset($p);
        $components=json_decode($t['components_json']??'[]',true)?:[];$extras=WhatsAppTemplateComponents::validate($components,$input['extra_parameters']??[]);
        if((int)$this->q("SELECT COUNT(*) FROM wa_marketing_campaigns WHERE user_id=? AND state IN ('draft','scheduled','running','paused','blocked')",[$uid])->fetchColumn()>=50)throw new InvalidArgumentException('Finish or cancel existing campaigns before creating more');
        $this->q('INSERT INTO wa_marketing_campaigns(user_id,website_id,name,template_name,language,template_body,template_hash,connection_hash,parameters_json,components_json,extra_parameters_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$uid,$wid,$name,$t['name'],$t['language'],$t['body'],$t['content_hash'],$t['connection_hash'],json_encode($parameters,JSON_THROW_ON_ERROR),json_encode($components,JSON_THROW_ON_ERROR),json_encode($extras,JSON_THROW_ON_ERROR)]);return $this->campaign($uid,(int)$this->pdo->lastInsertId());
    }
    public function campaign(int $uid,int $id): array{$c=$this->q('SELECT * FROM wa_marketing_campaigns WHERE id=? AND user_id=?',[$id,$uid])->fetch(PDO::FETCH_ASSOC);if(!$c)throw new InvalidArgumentException('Campaign not found');$this->owned($uid,(int)$c['website_id']);$counts=[];foreach($this->q('SELECT state,COUNT(*) n FROM wa_marketing_recipients WHERE campaign_id=? GROUP BY state',[$id])->fetchAll(PDO::FETCH_ASSOC) as $v)$counts[$v['state']]=(int)$v['n'];$c['counts']=$counts;return $c;}
    public function campaigns(int $uid,int $wid): array{$this->owned($uid,$wid);$rows=$this->q('SELECT id FROM wa_marketing_campaigns WHERE user_id=? AND website_id=? ORDER BY id DESC LIMIT 100',[$uid,$wid])->fetchAll(PDO::FETCH_ASSOC);return array_map(fn($r)=>$this->campaign($uid,(int)$r['id']),$rows);}
    public function recipients(int $uid,int $id,int $page=1): array{$this->campaign($uid,$id);if($page<1||$page>10000)throw new InvalidArgumentException('Invalid page');return $this->q('SELECT r.id,r.phone,r.name,r.language,r.state,r.provider_status,r.last_error,r.message_id,d.status delivery_status FROM wa_marketing_recipients r JOIN wa_marketing_campaigns c ON c.id=r.campaign_id LEFT JOIN whatsapp_delivery_statuses d ON d.website_id=c.website_id AND d.user_id=c.user_id AND BINARY d.wamid=r.message_id WHERE r.campaign_id=? ORDER BY r.id LIMIT 100 OFFSET '.(($page-1)*100),[$id])->fetchAll(PDO::FETCH_ASSOC);}
    public function launch(int $uid,int $id,array $ids,?string $scheduled): array
    {
        $c=$this->campaign($uid,$id);$this->syncTemplates($uid,(int)$c['website_id']);$stamp=$scheduled?InternationalSettingsService::scheduledTimestamp($uid,$scheduled):time();if($stamp<time()-60||$stamp>time()+365*86400)throw new InvalidArgumentException('Choose a send time within the next year');if(!$ids||count($ids)>500)throw new InvalidArgumentException('Choose 1–500 consented contacts per campaign');
        return $this->lock('wa_campaign:'.$id,function()use($uid,$id,$ids,$stamp){$c=$this->campaign($uid,$id);if($c['state']!=='draft')return $c;$this->ready($c);$this->pdo->beginTransaction();try{$lockedState=$this->q('SELECT state FROM wa_marketing_campaigns WHERE id=? FOR UPDATE',[$id])->fetchColumn();if($lockedState!=='draft'){$this->pdo->commit();return $this->campaign($uid,$id);}foreach(array_unique($ids) as $cid){$contact=$this->q('SELECT * FROM wa_marketing_contacts WHERE id=? AND user_id=? AND website_id=? FOR UPDATE',[(int)$cid,$uid,$c['website_id']])->fetch(PDO::FETCH_ASSOC);if(!$contact||$contact['consent_state']!=='opted_in')throw new InvalidArgumentException('Every selected contact must have explicit marketing consent');if(!self::compatible($contact['language'],$c['language']))throw new InvalidArgumentException('Contact language does not match the campaign template');$this->q('INSERT INTO wa_marketing_recipients(campaign_id,contact_id,phone,name,language) VALUES(?,?,?,?,?)',[$id,$contact['id'],$contact['phone'],$contact['name'],$contact['language']]);}$this->q("UPDATE wa_marketing_campaigns SET state='scheduled',scheduled_at=?,last_error=NULL WHERE id=?",[gmdate('Y-m-d H:i:s',$stamp),$id]);$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}return $this->campaign($uid,$id);});
