    private function ready(array $c): void{$row=$this->conn((int)$c['user_id'],(int)$c['website_id']);if(self::connectionHash($row)!==$c['connection_hash'])throw new InvalidArgumentException('Sender connection changed. Create a new draft for the new sender.');$t=$this->q("SELECT * FROM wa_marketing_templates WHERE user_id=? AND website_id=? AND name=? AND language=? AND status='APPROVED' AND supported=1",[$c['user_id'],$c['website_id'],$c['template_name'],$c['language']])->fetch(PDO::FETCH_ASSOC);if(!$t||$t['content_hash']!==$c['template_hash']||$t['connection_hash']!==$c['connection_hash'])throw new InvalidArgumentException('Template is missing, changed, paused or not approved');}
    public function action(int $uid,int $id,string $action): array
    {$c=$this->campaign($uid,$id);if($action==='pause'&&in_array($c['state'],['running','scheduled'],true))$this->q("UPDATE wa_marketing_campaigns SET state='paused' WHERE id=? AND state IN ('running','scheduled')",[$id]);elseif($action==='cancel'&&!in_array($c['state'],['completed','cancelled'],true)){$this->q("UPDATE wa_marketing_campaigns SET state='cancelled' WHERE id=?",[$id]);$this->q("UPDATE wa_marketing_recipients SET state='skipped',last_error='Campaign cancelled' WHERE campaign_id=? AND state='pending'",[$id]);}elseif($action==='resume'&&in_array($c['state'],['paused','blocked'],true)){$this->syncTemplates($uid,(int)$c['website_id']);$this->ready($c);$this->q("UPDATE wa_marketing_campaigns SET state='scheduled',last_error=NULL WHERE id=? AND state IN ('paused','blocked')",[$id]);}elseif($action==='retry'&&in_array($c['state'],['completed','partial'],true)){$this->ready($c);$this->q("UPDATE wa_marketing_recipients SET state='pending',last_error=NULL WHERE campaign_id=? AND state='failed' AND message_id IS NULL",[$id]);if($this->q("SELECT id FROM wa_marketing_recipients WHERE campaign_id=? AND state='pending' LIMIT 1",[$id])->fetchColumn())$this->q("UPDATE wa_marketing_campaigns SET state='scheduled',last_error=NULL WHERE id=?",[$id]);}else throw new InvalidArgumentException('This action is not available for the current campaign state');return $this->campaign($uid,$id);}
    public static function parameters(array $c,array $r,string $company): array{$values=json_decode($c['parameters_json'],true,512,JSON_THROW_ON_ERROR);$params=array_map(static fn($p)=>WhatsAppCloudAPI::cleanParam(strtr($p,['{{contact_name}}'=>$r['name'],'{{company_name}}'=>$company,'{{phone}}'=>$r['phone']])), $values);$names=WhatsAppTemplateComponents::variables($c['template_body']);return $names&&!ctype_digit($names[0])?array_combine($names,$params):$params;}
    private static function key(int $id,int $recipient): string{return 'wa_marketing:'.$id.':'.$recipient;}
    public function process(int $uid,int $id,int $limit=5): array
    {
        return $this->lock('wa_campaign:'.$id,function()use($uid,$id,$limit){$c=$this->campaign($uid,$id);try{$e=$this->q('SELECT state FROM wa_campaign_experiments WHERE user_id=? AND (campaign_a=? OR campaign_b=?) LIMIT 1',[$uid,$id,$id])->fetch(PDO::FETCH_ASSOC);if($e&&$e['state']!=='scheduled')return ['processed'=>0,'experiment_pending'=>true];}catch(PDOException $error){if($error->getCode()!=='42S02')throw $error;}if(!in_array($c['state'],['running','scheduled'],true)||strtotime($c['scheduled_at'].' UTC')>time())return ['processed'=>0];
