            $rows=$this->q("SELECT id FROM wa_marketing_recipients WHERE campaign_id=? AND state='pending' ORDER BY id LIMIT ".max(1,min(5,$limit)),[$id])->fetchAll(PDO::FETCH_ASSOC);
            foreach($rows as $row){if($this->campaign($uid,$id)['state']!=='running')break;$this->sendOne($c,(int)$row['id'],$api);$n++;}
