        });
    }
    private function sendOne(array $c,int $id,object $api): void
    {
        $r=$this->q('SELECT * FROM wa_marketing_recipients WHERE id=? AND campaign_id=?',[$id,$c['id']])->fetch(PDO::FETCH_ASSOC);if(!$r||$r['state']!=='pending')return;
        $this->lock('wa_marketing_phone:'.$c['user_id'].':'.$c['website_id'].':'.$r['phone'],function()use($c,$r,$api,$id){$contact=$this->q('SELECT * FROM wa_marketing_contacts WHERE id=? AND user_id=? AND website_id=?',[$r['contact_id'],$c['user_id'],$c['website_id']])->fetch(PDO::FETCH_ASSOC);$reason=null;
