            try{$result=ExternalExecution::run(self::key((int)$c['id'],$id),(int)$c['user_id'],function()use($api,$r,$c,$params){$result=$api->sendTemplate($r['phone'],$c['template_name'],$c['language'],$params,WhatsAppTemplateComponents::payload(json_decode($c['components_json']??'[]',true)?:[],json_decode($c['extra_parameters_json']??'[]',true)?:[],(string)$r['id']));$ok=!empty($result['ok'])&&!empty($result['id']);$code=(int)($result['http_code']??0);return ['success'=>$ok,'message_id'=>$ok?$result['id']:null,'status'=>$result['message_status']??'accepted','http_code'=>$code,'error'=>$ok?null:self::sendError((int)($result['error_code']??0)),'definitive_failure'=>!$ok&&$code>=400&&$code<500&&$code!==408&&$code!==429];});$state=!empty($result['success'])?'accepted':(($result['outcome_state']??'uncertain')==='failed'?'failed':'uncertain');$this->persistRecipient($c,$r,$state,$result);}catch(Throwable $e){$this->q("UPDATE wa_marketing_recipients SET state='uncertain',last_error='Send outcome is uncertain. Check Meta before any new send.' WHERE id=? AND state='processing'",[$id]);}
