    private function persistRecipient(array $c,array $r,string $state,array $result): void
    {
        $this->pdo->beginTransaction();try{
            $this->q('UPDATE wa_marketing_recipients SET state=?,message_id=?,provider_status=?,last_error=? WHERE id=?',[$state,$result['message_id']??null,$state==='accepted'?($result['status']??'accepted'):null,$state==='accepted'?null:($result['error']??'Provider rejected the request'),$r['id']]);
            if($state==='accepted')$this->q('UPDATE wa_marketing_contacts SET last_accepted_at=UTC_TIMESTAMP() WHERE id=? AND user_id=? AND website_id=?',[$r['contact_id'],$c['user_id'],$c['website_id']]);$this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function queueDue(int $limit=5): int
    {
        // Reconcile interrupted sends from durable evidence; unknown writes are never resent.
        foreach($this->q("SELECT r.*,c.user_id,c.website_id FROM wa_marketing_recipients r JOIN wa_marketing_campaigns c ON c.id=r.campaign_id WHERE r.state='processing' AND r.updated_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE) LIMIT 100")->fetchAll(PDO::FETCH_ASSOC) as $r){try{$this->lock('wa_campaign:'.$r['campaign_id'],function()use($r){$a=$this->q('SELECT state,result_json FROM external_execution_attempts WHERE operation_key=?',[hash('sha256',self::key((int)$r['campaign_id'],(int)$r['id']))])->fetch(PDO::FETCH_ASSOC);if($a&&$a['state']==='completed'){$result=json_decode($a['result_json'],true)?:[];$this->persistRecipient(['user_id'=>$r['user_id'],'website_id'=>$r['website_id']],$r,'accepted',$result);}else{$state=!$a?'pending':($a['state']==='failed'?'failed':'uncertain');$this->q("UPDATE wa_marketing_recipients SET state=?,last_error='Recovered after worker interruption; check status before retry' WHERE id=? AND state='processing'",[$state,$r['id']]);}});}catch(Throwable $e){}}
        $experimentFilter=$this->q("SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='wa_campaign_experiments'")->fetchColumn()?" AND NOT EXISTS (SELECT 1 FROM wa_campaign_experiments e WHERE e.user_id=c.user_id AND (e.campaign_a=c.id OR e.campaign_b=c.id) AND e.state<>'scheduled')":"";
        $this->q("UPDATE wa_marketing_campaigns SET job_pending=0 WHERE job_pending=1 AND updated_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE)");$n=0;
        foreach($this->q("SELECT c.id,c.user_id FROM wa_marketing_campaigns c JOIN websites w ON w.id=c.website_id AND w.user_id=c.user_id WHERE c.state IN ('scheduled','running') AND c.scheduled_at<=UTC_TIMESTAMP() AND c.job_pending=0".$experimentFilter." ORDER BY c.scheduled_at LIMIT ".max(1,min(10,$limit)))->fetchAll(PDO::FETCH_ASSOC) as $c){try{$this->lock('wa_campaign:'.$c['id'],function()use($c,&$n){$row=$this->campaign((int)$c['user_id'],(int)$c['id']);if($row['job_pending']||!in_array($row['state'],['scheduled','running'],true))return;$this->pdo->beginTransaction();try{$job=(new QueueManager())->push(WhatsAppMarketingJob::class,['campaign_id'=>(int)$c['id'],'user_id'=>(int)$c['user_id']],'whatsapp-marketing');if(!$job)throw new RuntimeException('Queue unavailable');$this->q('UPDATE wa_marketing_campaigns SET job_pending=1 WHERE id=?',[$c['id']]);$this->pdo->commit();$n++;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}});}catch(Throwable $e){}}return $n;
    }
    public static function isOptOut(string $text): bool{$s=mb_strtolower(trim($text));$s=preg_replace('/[.!؟،]+$/u','',$s);return in_array($s,['stop','unsubscribe','opt out','cancel','stop promotions','إلغاء','الغاء','توقف','arret','arrêt','arreter','arrêter','abmelden','baja','parar'],true);}
    public static function handleOptOut(int $wid,int $uid,array $payload): bool
    {if(!self::isOptOut((string)($payload['message']??'')))return false;$service=new self();$service->owned($uid,$wid);$phone=self::phone((string)($payload['phone_number']??''));$contact=$service->q('SELECT id FROM wa_marketing_contacts WHERE user_id=? AND website_id=? AND phone=?',[$uid,$wid,$phone])->fetchColumn();if($contact&&$service->q('SELECT consent_state FROM wa_marketing_contacts WHERE id=?',[$contact])->fetchColumn()!=='opted_out'){$service->q("UPDATE wa_marketing_contacts SET consent_state='opted_out',opted_out_at=UTC_TIMESTAMP(),consent_note='Customer opt-out received via WhatsApp' WHERE id=?",[$contact]);$service->q("INSERT INTO wa_marketing_consent_events(contact_id,user_id,website_id,state,evidence) VALUES(?,?,?,'opted_out','Customer opt-out received via WhatsApp')",[$contact,$uid,$wid]);}return true;}
    public static function installed(): bool
    {static $ready=null;if($ready===null){try{$pdo=Database::getInstance()->getConnection();$q=$pdo->prepare("SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='wa_marketing_contacts'");$q->execute();$ready=(bool)$q->fetchColumn();}catch(Throwable $e){$ready=false;}}return $ready;}
    public static function storeOptOutInbox(int $uid,int $wid,array $payload): void
    {
        $service=new self();$service->owned($uid,$wid);$known=$service->q("SELECT id FROM chat_messages WHERE user_id=? AND website_id=? AND platform='whatsapp' AND platform_message_id=?",[$uid,$wid,(string)$payload['platform_message_id']])->fetchColumn();if($known)return;
        $phone=self::phone((string)$payload['phone_number']);$message=new ChatMessage(['user_id'=>$uid,'website_id'=>$wid,'platform'=>'whatsapp','platform_message_id'=>(string)$payload['platform_message_id'],'customer_name'=>$payload['sender_name']??null,'customer_phone'=>$phone,'session_id'=>hash('sha256',$uid.'|'.$wid.'|'.$phone),'message_direction'=>'incoming','message_text'=>(string)$payload['message'],'message_language'=>$payload['language']??'en','bot_status'=>'rejected','is_auto_pilot'=>0]);
        if(!$message->save())throw new RuntimeException('Unable to store the customer opt-out in the inbox');
    }

    public static function sendError(int $code): string
    {return match($code){190=>'Access token expired or revoked. Reconnect the sender.',131049=>'Meta restricted marketing delivery to this recipient. Do not retry immediately.',131026=>'The message could not be delivered to this recipient.',131030=>'Recipient is not allowed for this Meta test account.',132000=>'Template parameter count does not match.',132001=>'Template name/language is unavailable in this account.',132007,132015=>'Meta rejected or paused this template.',131042=>'Check the payment method in WhatsApp Business Manager.',default=>'Meta did not confirm this send (code '.$code.'). Review the provider status.'};}

